<?php
require __DIR__.'/includes/module.php';$u=require_auth();require_permission('quotations.edit');$customers=db()->prepare('SELECT id,name,company FROM customers WHERE business_id=? AND archived_at IS NULL ORDER BY name');$customers->execute([$u['business_id']]);$customerRows=$customers->fetchAll();$products=db()->prepare('SELECT id,name,unit,price,tax_rate FROM products WHERE business_id=? AND active=1 ORDER BY name');$products->execute([$u['business_id']]);$productRows=$products->fetchAll();page_start('Create quotation','quotations');module_css('quotation-create');?><div class="section-head"><div><span class="eyebrow">SALES</span><h1>Create quotation</h1><p>Prepare a clear estimate and preserve it when accepted.</p></div><a class="button secondary" href="quotations.php">Cancel</a></div><form method="post" class="content-card simple-form"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="create"><div class="modal-form"><label>Customer *<select name="customer_id" required><option value="">Select customer</option><?php foreach($customerRows as $c):?><option value="<?=(int)$c['id']?>" <?=((int)($_GET['customer']??0)===(int)$c['id'])?'selected':''?>><?=e($c['name'].($c['company']?' · '.$c['company']:''))?></option><?php endforeach?></select></label><label>Quotation date<input required type="date" name="quotation_date" value="<?=e(date('Y-m-d'))?>"></label><label>Valid until<input type="date" name="valid_until" value="<?=e(date('Y-m-d',strtotime('+14 days')))?>"></label><label class="wide">Items</label></div><div id="quote-lines"><div class="invoice-line"><select class="quote-product"><option value="">Choose catalog item or type below</option><?php foreach($productRows as $p):?><option value="<?=e(json_encode(['name'=>$p['name'],'unit'=>$p['unit'],'price'=>(float)$p['price'],'tax'=>(float)$p['tax_rate']],JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_TAG|JSON_HEX_AMP))?>"><?=e($p['name'])?></option><?php endforeach?></select><input name="description[]" required placeholder="Description"><input name="quantity[]" type="number" min="0.001" step="0.001" value="1" required placeholder="Qty"><input name="rate[]" type="number" min="0" step="0.01" value="0" required placeholder="Rate"><input name="tax_rate[]" type="number" min="0" max="100" step="0.001" value="0" placeholder="Tax %"><button type="button" class="link-button remove-line">×</button></div></div><button type="button" class="link-button" id="add-line"><i class="ti ti-plus"></i> Add line item</button><div class="invoice-total"><span>Subtotal <b id="subtotal">₹ 0.00</b></span><span>Tax <b id="tax-total">₹ 0.00</b></span><strong>Quotation total <b id="grand-total">₹ 0.00</b></strong></div><label class="form-notes">Notes / terms<textarea name="notes" placeholder="Validity, scope, payment terms"></textarea></label><button class="button primary"><i class="ti ti-device-floppy"></i> Save quotation draft</button></form><script>const lineBox=document.getElementById('quote-lines');document.getElementById('add-line').onclick=()=>{const row=lineBox.firstElementChild.cloneNode(true);row.querySelectorAll('input').forEach(x=>{x.value=x.name==='quantity[]'?'1':(x.name==='rate[]'||x.name==='tax_rate[]'?'0':'')});row.querySelector('select').selectedIndex=0;lineBox.append(row);};lineBox.addEventListener('change',e=>{if(!e.target.matches('.quote-product')||!e.target.value)return;const data=JSON.parse(e.target.value),row=e.target.closest('.invoice-line');row.querySelector('[name="description[]"]').value=data.name;row.querySelector('[name="rate[]"]').value=data.price;row.querySelector('[name="tax_rate[]"]').value=data.tax;});lineBox.addEventListener('input',calc);lineBox.addEventListener('click',e=>{if(e.target.closest('.remove-line')&&lineBox.children.length>1){e.target.closest('.invoice-line').remove();calc()}});function calc(){let s=0,t=0;lineBox.querySelectorAll('.invoice-line').forEach(r=>{let q=+r.querySelector('[name="quantity[]"]').value||0,p=+r.querySelector('[name="rate[]"]').value||0,x=+r.querySelector('[name="tax_rate[]"]').value||0;s+=q*p;t+=q*p*x/100});document.getElementById('subtotal').textContent='₹ '+s.toLocaleString('en-IN',{minimumFractionDigits:2});document.getElementById('tax-total').textContent='₹ '+t.toLocaleString('en-IN',{minimumFractionDigits:2});document.getElementById('grand-total').textContent='₹ '+(s+t).toLocaleString('en-IN',{minimumFractionDigits:2})}lineBox.addEventListener('change',calc);calc();</script><style>.invoice-line{display:grid;grid-template-columns:1.15fr 1.4fr .55fr .8fr .65fr 20px;gap:6px;margin:8px 0}.invoice-line input,.invoice-line select{min-width:0;width:100%;height:34px;border:1px solid #e5e9ed;border-radius:6px;padding:0 7px;font-size:10px}.invoice-total{display:grid;gap:8px;justify-content:end;margin:16px 0;color:#858f9b;font-size:10px}.invoice-total span,.invoice-total strong{display:flex;gap:35px;justify-content:space-between}.invoice-total strong{border-top:1px solid #edf0f2;padding-top:9px;color:#2e3b49;font-size:12px}.form-notes{display:block;color:#788391;font-size:10px;margin:14px 0}.form-notes textarea{display:block;width:100%;height:65px;margin-top:5px;border:1px solid #e5e9ed;border-radius:6px;padding:8px}@media(max-width:720px){.invoice-line{grid-template-columns:1fr 1fr}.invoice-line select,.invoice-line input:first-of-type{grid-column:span 2}}</style><?php page_end();
